package io.github.warfolame.moveorder.domain;

import java.util.UUID;

/**
 * Surrogate identifier of a move order. Generated by us, never shown to the customer
 * and never changes. The number people see is {@link MoveOrderNumber}.
 *
 * @param value the UUID; must not be null
 */
public record MoveOrderId(UUID value) {

    public MoveOrderId {
        if (value == null) {
            throw new IllegalArgumentException("MoveOrderId must not be null");
        }
    }

    /** A new, random identifier for a new order. */
    public static MoveOrderId newId() {
        return new MoveOrderId(UUID.randomUUID());
    }
}
